NODE_PATH=$(npm root -g) node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Get product details (name + price)
const products = db.prepare('SELECT product_id, name, price FROM products').all();
const productMap = {};
for (const p of products) {
  productMap[p.product_id] = { name: p.name, price: p.price };
}

// Get all non-empty carts with their items and user info
const carts = db.prepare('SELECT * FROM carts WHERE subtotal > 0').all();
for (const cart of carts) {
  const user = db.prepare('SELECT name, email FROM users WHERE user_id = ?').get(cart.customer_id);
  const items = db.prepare('SELECT * FROM cart_items WHERE cart_id = ?').all(cart.cart_id);
  console.log('========================================');
  console.log('Cart ID:', cart.cart_id);
  console.log('Customer:', cart.customer_id, user ? '(' + user.name + ', ' + user.email + ')' : '');
  console.log('Shipping:', cart.shipping_option, '- Cost: \$' + cart.shipping_cost);
  console.log('----------------------------------------');
  for (const item of items) {
    const prod = productMap[item.product_id] || { name: 'Unknown', price: '?' };
    console.log('  Item:', item.cart_item_id);
    console.log('    Product:', prod.name, '(' + item.product_id + ')');
    console.log('    Quantity:', item.quantity);
    console.log('    Unit Price: \$' + prod.price);
    console.log('    Gift Wrap:', item.gift_wrap ? 'Yes' : 'No');
  }
  console.log('----------------------------------------');
  console.log('Subtotal: \$' + cart.subtotal);
  console.log('Discount: \$' + cart.discount_amount);
  console.log('Shipping: \$' + cart.shipping_cost);
  console.log('Total:    \$' + cart.total);
}
db.close();
"

NODE_PATH=$(npm root -g) node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// 1. Update CI-0006 quantity from 3 to 2
db.prepare('UPDATE cart_items SET quantity = 2 WHERE cart_item_id = ? AND cart_id = ?')
  .run('CI-0006', 'CART-user_58b0a2d6');
console.log('✓ Updated CI-0006 (RidgeLine Fleece Zip Hoodie) quantity: 3 → 2');

// 2. Remove CI-0005
db.prepare('DELETE FROM cart_items WHERE cart_item_id = ? AND cart_id = ?')
  .run('CI-0005', 'CART-user_58b0a2d6');
console.log('✓ Removed CI-0005 (Harbor Cotton Crew Tee)');

// 3. Recalculate cart totals
// Remaining items: CI-0006 (2 × \$89 = \$178) + CI-0007 (2 × \$72 = \$144)
const items = db.prepare('SELECT ci.quantity, p.price FROM cart_items ci JOIN products p ON ci.product_id = p.product_id WHERE ci.cart_id = ?')
  .all('CART-user_58b0a2d6');
const subtotal = items.reduce((sum, i) => sum + (i.quantity * i.price), 0);

// Update cart: subtotal, total, and item_ids_json
const remainingIds = db.prepare('SELECT cart_item_id FROM cart_items WHERE cart_id = ?')
  .all('CART-user_58b0a2d6').map(r => r.cart_item_id);
const itemIdsJson = JSON.stringify(remainingIds);

db.prepare('UPDATE carts SET subtotal = ?, total = ?, item_ids_json = ? WHERE cart_id = ?')
  .run(subtotal, subtotal + 0 /* shipping is 0 */, itemIdsJson, 'CART-user_58b0a2d6');
console.log('✓ Cart totals recalculated');

// 4. Verify final state
const cart = db.prepare('SELECT * FROM carts WHERE cart_id = ?').get('CART-user_58b0a2d6');
const finalItems = db.prepare(\`
  SELECT ci.cart_item_id, p.name, ci.quantity, p.price, ci.product_id
  FROM cart_items ci JOIN products p ON ci.product_id = p.product_id
  WHERE ci.cart_id = ?
\`).all('CART-user_58b0a2d6');

console.log('\n=== Updated Cart ===');
for (const item of finalItems) {
  console.log('  ' + item.cart_item_id + ': ' + item.name + ' | Qty: ' + item.quantity + ' | \$' + item.price + ' ea | Line: \$' + (item.quantity * item.price));
}
console.log('Subtotal: \$' + cart.subtotal);
console.log('Shipping: \$' + cart.shipping_cost);
console.log('Total:    \$' + cart.total);

db.close();
"

